import{_ as e,o as r,c as t,a3 as c}from"./chunks/framework.BzWmN0d8.js";const u=JSON.parse('{"title":"故障排查与 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/troubleshooting.md","filePath":"zh/guide/troubleshooting.md","lastUpdated":1788425513000}'),d={name:"zh/guide/troubleshooting.md"};function n(s,o,l,a,i,g){return r(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="故障排查与-faq" tabindex="-1">故障排查与 FAQ <a class="header-anchor" href="#故障排查与-faq" aria-label="Permalink to &quot;故障排查与 FAQ&quot;">​</a></h1><p>针对最常见的&quot;为什么看不到日志&quot;场景，提供自查清单。</p><h2 id="_1-console-输出导致无限递归-栈溢出" tabindex="-1">1. Console 输出导致无限递归 / 栈溢出 <a class="header-anchor" href="#_1-console-输出导致无限递归-栈溢出" aria-label="Permalink to &quot;1. Console 输出导致无限递归 / 栈溢出&quot;">​</a></h2><p><strong>现象：</strong> 一打日志应用就卡死，或抛出 <code>Maximum call stack size exceeded</code>。</p><p><strong>原因：</strong> 某个 transport（传输器，即日志的输出目的地）或 formatter（格式化器）/ plugin（插件）调用了 <code>console.log</code>/<code>console.error</code>， 而<em>你</em>通过 <code>redirectConsole()</code> 把 console 重定向进了 <code>lograil</code>。注意：<code>lograil</code> <strong>默认不会</strong> 重定向 <code>console.*</code>——只有你显式调用 <code>logger.redirectConsole()</code> 才会。被重定向的 <code>console.*</code> 又回调 logger → 死循环。</p><p><strong>自查</strong></p><ul><li>是否调用了 <code>redirectConsole()</code>？如果是，它会接管 <code>console.*</code> 并重新经 logger 输出，你自己的 transport（传输器）/插件<strong>不要</strong>对相同级别再调 <code>console.*</code>。若<strong>未</strong>调用它，请跳过本节——你的递归来自 别处（例如某 transport 直接调用了 <code>console</code>）。</li><li>在 <code>onError</code> 或自定义 transport 内，请使用<strong>原始</strong> console（<code>console.error</code>）—— <code>lograil</code> 特意保留了重定向前的引用；若你自己捕获了 <code>console</code>，改用 <code>process.stderr</code> 或专门的 stderr sink（<strong>sink</strong> 即数据的最终目的地）。</li></ul><p><strong>解决：</strong> 在错误处理与自定义 sink 中写 <code>process.stderr</code>/文件，或改用不会回灌到被重定向 console 的 transport（传输器）。</p><h2 id="_2-浏览器打包报错-无法解析-node-fs-node-path-node-os" tabindex="-1">2. 浏览器打包报错：无法解析 <code>node:fs</code> / <code>node:path</code> / <code>node:os</code> <a class="header-anchor" href="#_2-浏览器打包报错-无法解析-node-fs-node-path-node-os" aria-label="Permalink to &quot;2. 浏览器打包报错：无法解析 `node:fs` / `node:path` / `node:os`&quot;">​</a></h2><p><strong>现象：</strong> webpack / Vite / Rollup 在打包引入 <code>lograil</code> 的页面时报 <code>Module not found: Can&#39;t resolve &#39;node:fs&#39;</code> 或 <code>Failed to resolve import &quot;node:fs/promises&quot;</code>。</p><p><strong>原因：</strong> <code>lograil</code> 版本过旧。新版本从不直接解析 Node 内置模块——它们经过内部的 <code>shims</code> 层，构建时由 <code>browser</code> 字段替换为浏览器 stub，因此引入能顺利解析（打包器集成测试已验证）。</p><p><strong>修复：</strong> 升级 <code>lograil</code> 到最新版。若已是最新版本仍报错，检查打包器是否关闭了 <code>browser</code> 映射，或是否从绕过 <code>browser</code> 字段的路径（如不走构建的 CDN）引入。</p><h2 id="_3-渲染进程没有日志" tabindex="-1">3. 渲染进程没有日志 <a class="header-anchor" href="#_3-渲染进程没有日志" aria-label="Permalink to &quot;3. 渲染进程没有日志&quot;">​</a></h2><p><strong>现象：</strong> 主进程正常，渲染进程静默（或渲染日志始终到不了主进程的 <code>renderer.log</code> 文件）。</p><p><strong>背景：</strong> 在默认的 Electron runtime（运行时）下这是<strong>自动</strong>的——渲染端 logger 会自动经 IPC（进程间通信）把日志 转发到主进程，主端 logger 会写到独立的 <code>renderer.{date}.log</code>。通常你什么都不用做。若仍不工作， 通常是以下之一：你主动退出了自动接线、用非 Electron 的 runtime 构造了 logger，或渲染端 无法访问 <code>electron</code> 模块而静默回退到 Web runtime。</p><p><strong>自查</strong></p><ul><li>是否使用了默认的 <code>logger</code> / <code>createLogger()</code>（未显式传 <code>runtime</code>）？若是，转发与接收已由 框架接好——无需手动添加 <code>ElectronIpcTransport</code> 或调用 <code>registerIpcReceiver</code>。</li><li>若你<strong>主动退出</strong>（<code>createElectronRendererRuntime({ forwardToMain: false })</code> 或 <code>createElectronMainRuntime({ receiveFromRenderer: false })</code>）或用了自定义 runtime：是否在 <strong>渲染端</strong>手动添加了 <code>ElectronIpcTransport</code>，并在<strong>主进程</strong>调用了 <code>registerIpcReceiver((entry) =&gt; logger.ingestEntry(entry))</code>？</li><li>channel 是否正确？两侧默认都是 <code>lograil:log</code>（<code>LOGRAIL_CHANNEL</code>）；若覆盖需<strong>两侧</strong>一致。</li><li>打包后 <code>contextIsolation: true</code> + <code>nodeIntegration: false</code> 的环境下，渲染端无法 <code>require(&#39;electron&#39;)</code>，于是 lograil 无法识别 Electron 并回退到 Web runtime（仅本地 console）。 用 preload 桥接，并通过 <code>createElectronRendererRuntime({ ipcRenderer })</code> 传入（见 <a href="./runtime-electron">Electron 指南</a>）。</li><li>临时把级别调低（<code>logger.setLevel(&#39;trace&#39;)</code>）排除级别过滤问题。</li></ul><p>详见 <a href="./runtime-electron">Electron 指南</a>。</p><h2 id="_4-otlp-端点收不到任何数据" tabindex="-1">4. OTLP 端点收不到任何数据 <a class="header-anchor" href="#_4-otlp-端点收不到任何数据" aria-label="Permalink to &quot;4. OTLP 端点收不到任何数据&quot;">​</a></h2><p><strong>现象：</strong> 已添加 <code>OtlpTransport</code>，但 collector 里没有日志。</p><p><strong>自查</strong></p><ul><li>transport 所在进程能否访问该端点？（Electron 渲染进程的网络出口可能受限；建议从主进程 发送，或用 <code>ElectronIpcTransport</code> 把渲染日志转发到主进程。）</li><li><code>OtlpTransport</code> 是<strong>批量</strong>发送的（<code>batchSize</code>，默认 100），异步 flush。快速验证可在运行 结束时 <code>await logger.flush()</code>，或调小 <code>batchSize</code>。</li><li><code>fetch</code> 失败会通过 <code>onError</code> 上报（默认 <code>console.error</code>）。显式设置 <code>onError</code> 以查看 HTTP/连接错误。</li><li>确认 collector URL：OTLP/HTTP JSON 期望 <code>…/v1/logs</code>。404/401 通常是路径或鉴权头错误。</li><li>防火墙 / 代理：请求就是普通 <code>fetch</code>，确保允许出网。</li></ul><h2 id="_5-日志文件不轮转" tabindex="-1">5. 日志文件不轮转 <a class="header-anchor" href="#_5-日志文件不轮转" aria-label="Permalink to &quot;5. 日志文件不轮转&quot;">​</a></h2><p><strong>现象：</strong> 单个文件持续增大，或没有出现按日期的文件。</p><p><strong>自查</strong></p><ul><li><code>FileTransport</code> 仅在具备 Node <code>fs</code> 的环境生效——即<strong>主进程</strong> / Node 运行时，而非 浏览器或渲染进程 Web Worker。</li><li><code>rotate-time</code> 模式（默认）写入 <code>&lt;appName&gt;.{YYYY-MM-DD}.0.log</code>。检查日期戳格式与目录可写性； 目录会自动创建（<code>mkdir -p</code>）。</li><li>轮转触发条件：写入将导致超过 <code>maxSize</code>（<code>rotate-size</code> / <code>single-truncate</code>），或跨越 <code>hour</code>/<code>day</code> 边界（<code>rotate-time</code>），或你的 <code>shouldRotate</code> 谓词返回 <code>true</code>（<code>rotate-custom</code>）。 <code>maxSize</code> 过小 / 写入量大时轮转会很频繁；请确认 <code>maxFiles</code> 允许保留多于一代。</li><li>文件句柄会在<strong>第一次</strong>真正写入日志时才打开。若从未打过日志，就不会创建文件——这是预期行为。</li></ul><h2 id="_6-日志乱序-在多个-transport-间重复" tabindex="-1">6. 日志乱序 / 在多个 transport 间重复 <a class="header-anchor" href="#_6-日志乱序-在多个-transport-间重复" aria-label="Permalink to &quot;6. 日志乱序 / 在多个 transport 间重复&quot;">​</a></h2><p><code>lograil</code> 在多个 transport（传输器）间共享同一个不可变、冻结的条目（共享引用）。每个 transport（传输器）的异步 写入各有独立队列，因此慢 transport（传输器）可能落后于快 transport（传输器）——<strong>顺序仅在单个 transport（传输器）内 保证</strong>，而非跨 transport（传输器）全局保证。若需严格全局顺序，使用单一 transport（传输器）或让所有写入同步。 重复行通常是同一 transport（传输器）被加了两次，或 <code>redirectConsole()</code> 重复发出——用 <code>getTransports()</code> 核对。</p><h2 id="_7-跨进程-ipc-传递时的注意事项" tabindex="-1">7. 跨进程（IPC）传递时的注意事项 <a class="header-anchor" href="#_7-跨进程-ipc-传递时的注意事项" aria-label="Permalink to &quot;7. 跨进程（IPC）传递时的注意事项&quot;">​</a></h2><p>条目经 Electron IPC 发送时会做结构化克隆。条目越过边界后，在另一端是<strong>全新的独立对象</strong>。不要依赖对象同一性； 依赖字段值。详见<a href="./immutability">不可变性</a>。</p>',30)])])}const h=e(d,[["render",n]]);export{u as __pageData,h as default};
